#include <NimBLEDevice.h>

// ===== RGB LED =====
// Общий катод. Если анод общий — замени в setColor на 255 - x
#define PIN_R 4
#define PIN_G 5
#define PIN_B 6

// ===== Nordic UART Service — понимают все BLE-терминалы =====
#define SERVICE_UUID           "6E400001-B5A3-F393-E0A9-E50E24DCCA9E"
#define CHARACTERISTIC_UUID_RX "6E400002-B5A3-F393-E0A9-E50E24DCCA9E"
#define CHARACTERISTIC_UUID_TX "6E400003-B5A3-F393-E0A9-E50E24DCCA9E"

NimBLEServer* pServer = nullptr;
NimBLECharacteristic* pTxCharacteristic = nullptr;
volatile bool deviceConnected = false;
std::string rxBuf = "";

void setColor(int r, int g, int b) {
  analogWrite(PIN_R, r);
  analogWrite(PIN_G, g);
  analogWrite(PIN_B, b);
}

void sendToPhone(const std::string& msg) {
  if (deviceConnected) {
    pTxCharacteristic->setValue(msg);
    pTxCharacteristic->notify();
  }
}

void handleCommand(const std::string& line) {
  int r = -1, g = -1, b = -1;
  if (sscanf(line.c_str(), "R: %d G: %d B: %d", &r, &g, &b) == 3 &&
      r >= 0 && r <= 255 && g >= 0 && g <= 255 && b >= 0 && b <= 255) {
    setColor(r, g, b);
    char reply[48];
    snprintf(reply, sizeof(reply), "OK: R:%d G:%d B:%d\n", r, g, b);
    sendToPhone(reply);
    Serial.printf("[LED] R:%d G:%d B:%d\n", r, g, b);
  } else {
    sendToPhone("Ошибка. Формат: R: 0-255 G: 0-255 B: 0-255\n");
    Serial.println("[BT] Не понял команду: " + line);
  }
}

class ServerCallbacks : public NimBLEServerCallbacks {
  void onConnect(NimBLEServer* s, NimBLEConnInfo& info) override {
    deviceConnected = true;
    Serial.println("[BT] Клиент подключился");
  }
  void onDisconnect(NimBLEServer* s, NimBLEConnInfo& info, int reason) override {
    deviceConnected = false;
    Serial.println("[BT] Отключился, снова рекламируюсь...");
    NimBLEDevice::startAdvertising();
  }
};

class RxCallbacks : public NimBLECharacteristicCallbacks {
  void onWrite(NimBLECharacteristic* c, NimBLEConnInfo& info) override {
    rxBuf += c->getValue();
    size_t pos;
    while ((pos = rxBuf.find('\n')) != std::string::npos) {
      std::string line = rxBuf.substr(0, pos);
      rxBuf.erase(0, pos + 1);
      if (!line.empty()) handleCommand(line);
    }
  }
};

void setup() {
  Serial.begin(115200);
  pinMode(PIN_R, OUTPUT);
  pinMode(PIN_G, OUTPUT);
  pinMode(PIN_B, OUTPUT);
  setColor(0, 0, 0);

  NimBLEDevice::init("ESP32 RGB Beacon");

  pServer = NimBLEDevice::createServer();
  pServer->setCallbacks(new ServerCallbacks());

  NimBLEService* pService = NimBLEDevice::createService(SERVICE_UUID);

  pTxCharacteristic = pService->createCharacteristic(
      CHARACTERISTIC_UUID_TX,
      NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::NOTIFY);

  NimBLECharacteristic* pRx = pService->createCharacteristic(
      CHARACTERISTIC_UUID_RX,
      NIMBLE_PROPERTY::WRITE | NIMBLE_PROPERTY::WRITE_NR);
  pRx->setCallbacks(new RxCallbacks());

  pService->start();

  NimBLEAdvertising* pAdv = NimBLEDevice::getAdvertising();
  pAdv->addServiceUUID(SERVICE_UUID);
  pAdv->start();

  Serial.println("BLE сервер + RGB-управление запущены");
}

void loop() {
  delay(1000);
}
